ties"],"wells_basis":"derived from name/blurb/hook","si_all":["adventure","tropical"],"shelf_fit":{"adventure":"primary","diveglobal":"destination","entertainment":"destination","family":"destination","ocean":"destination","romance":"destination","sports":"destination","tropical":"evidenced"},"commission_pct_low":8,"commission_pct_high":12,"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"band+lane"},{"name":"ATV/buggy + Monkeyland ziplines + Macao horseback","si_tag":"globaladv","status":"live","tier":"essential","price_band":"~$60-150/pp","timing":"Dec-Apr","draw_rank":3,"when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"off-road buggies, rainforest ziplines with monkeys, and cantering a horse along Macao beach — the adventure-and-equine collection","si":"adventure","blurb":"off-road buggies, rainforest ziplines with monkeys, and cantering a horse along Macao beach — the adventure-and-equine collection","when":"Dec-Apr","commission":"DMC + affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["adventure","tropical"],"shelf_fit":{"adventure":"primary","diveglobal":"destination","entertainment":"destination","family":"destination","ocean":"destination","romance":"destination","sports":"destination","tropical":"evidenced"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"The catamaran snorkel cruise","si_tag":"ocean","status":"live","tier":"essential","price_band":"~$50-120/pp","timing":"year-round","draw_rank":1,"hook":"a coastal party-catamaran with snorkel stop, natural pool and open bar — the easy, sociable water day off the resort beach","si":"ocean","blurb":"a coastal party-catamaran with snorkel stop, natural pool and open bar — the easy, sociable water day off the resort beach","when":"year-round","commission":"DMC + Viator/GYG 8-12%","wells":["stay","move","activities"],"wells_basis":"derived from name/blurb/hook",